<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\{Guest,LoyaltyAccount,LoyaltyTier}; use App\Services\CRM\LoyaltyService; use Illuminate\Http\Request;
class LoyaltyController extends Controller {public function index(){ $p=auth()->user()->property_id; return view('crm.loyalty',['tiers'=>LoyaltyTier::where('property_id',$p)->orderBy('minimum_points')->get(),'accounts'=>LoyaltyAccount::where('property_id',$p)->with(['guest','tier'])->orderByDesc('lifetime_points')->paginate(25)]);} public function tier(Request $r){$d=$r->validate(['name'=>'required|string|max:100','minimum_points'=>'required|integer|min:0','discount_percent'=>'required|numeric|min:0|max:100','points_multiplier'=>'required|numeric|min:0','benefits'=>'nullable|string']);$d['property_id']=auth()->user()->property_id;$d['benefits']=$d['benefits']?array_values(array_filter(array_map('trim',explode(',',$d['benefits'])))):[];LoyaltyTier::create($d);return back()->with('success','Loyalty tier created.');} public function adjust(Request $r,Guest $guest,LoyaltyService $s){abort_unless($guest->property_id===auth()->user()->property_id,403);$d=$r->validate(['points'=>'required|integer|not_in:0','description'=>'required|string|max:255']);$d['points']>0?$s->add($guest,$d['points'],$d['description'],null,auth()->id()):$s->redeem($guest,abs($d['points']),$d['description'],null,auth()->id());return back()->with('success','Loyalty points updated.');}}
